    bauart,
    capexKwp,
    entwicklungKwp,
    netzKm,
    modell,
    preisCt: modell === "merchant" ? merchantCt : preisCt,
    vertragJahre,
    merchantCt,
    pachtHa,
    opexKwp,
    degradation,
    fkQuote,
    zins,
    tilgungJahre,
    laufzeit,
