}

function InvestZeile({ inv }) {
  const teile = [
    ["Speichersystem", inv.system, FARBEN.gruen],
    ["Netzanschluss", inv.netz, FARBEN.navy],
    ["Baukostenzuschuss", inv.bkz, FARBEN.sunHell],
  ].filter(([, v]) => v > 0);
