cd "C:/Users/SALEAD~1/AppData/Local/Temp/claude/c--Users-SALEADMIN-Downloads-Oekovolt-Web-DE-Oekovolt-Web-DE/6ac8640b-bab4-4de9-9c07-3a24f91b0e42/scratchpad/pw" && cat > t6_audit.mjs <<'EOF'
// t6_audit.mjs – Prüft die sechs neuen Rechner (Status, Laufzeitfehler, Überlauf 390/1440, tote Links, Interaktion)
import { chromium } from "playwright";
const B = "http://localhost:3100";
const pfade = ["/rechner/pachtangebot-check", "/rechner/ppa", "/rechner/grossspeicher", "/rechner/beteiligung", "/rechner/energy-sharing", "/rechner/netzanschluss"];
const b = await chromium.launch();
const probleme = []; const links = new Set();
for (const breite of [390, 1440]) {
  const ctx = await b.newContext({ viewport: { width: breite, height: breite < 600 ? 844 : 900 } });
  for (const pfad of pfade) {
    const p = await ctx.newPage(); const fehler = [];
    p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message.slice(0, 200)));
    p.on("console", (m) => m.type() === "error" && !/hydrat/i.test(m.text()) && fehler.push("CONSOLE " + m.text().slice(0, 200)));
    let st = 0;
    try { const r = await p.goto(B + pfad, { waitUntil: "load", timeout: 180000 }); st = r.status(); } catch (e) { fehler.push("GOTO " + e.message.slice(0, 80)); }
    await p.waitForTimeout(800);
    // Interaktion: alle Range-Regler auf Min/Max schieben, alle Radios anklicken, Schalter umschalten
    const aktionen = await p.evaluate(async () => {
      const setze = (el, v) => { const s = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set; s.call(el, v); el.dispatchEvent(new Event("input", { bubbles: true })); el.dispatchEvent(new Event("change", { bubbles: true })); };
      let n = 0;
      for (const el of document.querySelectorAll("main input[type=range]")) { setze(el, el.max); n++; await new Promise((r) => setTimeout(r, 15)); setze(el, el.min); await new Promise((r) => setTimeout(r, 15)); }
      for (const el of document.querySelectorAll("main input[type=radio]")) { el.click(); n++; await new Promise((r) => setTimeout(r, 10)); }
      for (const el of document.querySelectorAll("main input[role=switch]")) { el.click(); n++; await new Promise((r) => setTimeout(r, 10)); el.click(); }
      return n;
    });
    await p.waitForTimeout(600);
    const text = await p.evaluate(() => document.querySelector("main")?.innerText || "");
    if (/NaN|undefined|Infinity/.test(text)) fehler.push("TEXT enthält NaN/undefined/Infinity: " + (text.match(/.{0,40}(NaN|undefined|Infinity).{0,40}/) || [""])[0]);
    const info = await p.evaluate(() => {
      const w = document.documentElement.scrollWidth, iw = window.innerWidth;
      const breit = [...document.querySelectorAll("main *")].filter((el) => { const r = el.getBoundingClientRect(); return r.right > iw + 2 && r.width > 0 && getComputedStyle(el).position !== "fixed"; }).slice(0, 3).map((el) => el.tagName + "." + String(el.className).slice(0, 60));
      return { w, iw, breit, links: [...document.querySelectorAll("a[href^='/']")].map((a) => a.getAttribute("href").split("#")[0].split("?")[0]) };
    });
    info.links.forEach((l) => l && links.add(l));
    if (st !== 200 || fehler.length || info.w > info.iw + 1) probleme.push({ breite, pfad, st, ueberlauf: info.w > info.iw + 1 ? `${info.w}px ${info.breit.join(" | ")}` : undefined, fehler });
    console.log(breite, pfad, st, "Aktionen", aktionen, fehler.length ? "FEHLER" : "ok");
    await p.close();
  }
  await ctx.close();
}
for (const l of links) { if (/^\/(api|_next)/.test(l)) continue; const r = await fetch(B + l, { redirect: "manual" }); if (r.status >= 400) probleme.push({ link: l, st: r.status }); }
console.log("Links geprüft:", links.size);
console.log(JSON.stringify(probleme, null, 1));
await b.close();
EOF
MSYS_NO_PATHCONV=1 node t6_audit.mjs

